(()=>{window.__qaAfter=null;(async()=>{try{
const all=await new Promise((resolve,reject)=>{const req=indexedDB.open('xray-chat-history-v1',1);
 req.onupgradeneeded=()=>req.result.createObjectStore('projects',{keyPath:'projectId'});
 req.onsuccess=()=>{const db=req.result;const q=db.transaction('projects').objectStore('projects').getAll();
  q.onsuccess=()=>{db.close();resolve(q.result||[])};q.onerror=()=>{db.close();reject(q.error)}};
 req.onerror=()=>reject(req.error)});
const SENT='RSTRT-21-A7';const hits=[];
for(const p of all) for(const t of (p.threads||[])) for(const e of (t.entries||[])){
 if(e.kind!=='user')continue; if((e.text||'').includes(SENT)) hits.push({projectId:p.projectId,threadId:t.id,text:(e.text||'').slice(0,200)});}
let active=null;try{const s=await import('/src/studio/store.ts');const j=s.useStudio.getState().job;active={id:j.id,name:j.name,revision:j.revision,documents:(j.documents||[]).length}}catch(e){active='ERR:'+e}
window.__qaAfter={sentinelFound:hits.length>0,hits,projects:all.length,
 projectsDetail:all.map(p=>({projectId:p.projectId,revision:p.revision,threads:(p.threads||[]).length,
  assistantEntries:(p.threads||[]).reduce((n,t)=>n+(t.entries||[]).filter(e=>e.kind==='assistant').length,0),
  userEntries:(p.threads||[]).reduce((n,t)=>n+(t.entries||[]).filter(e=>e.kind==='user').length,0),
  toolEntries:(p.threads||[]).reduce((n,t)=>n+(t.entries||[]).filter(e=>e.kind==='tool').length,0)})),
 localStorageKeys:Object.keys(localStorage).length,activeJob:active};
}catch(e){window.__qaAfter={error:String(e)}}})();return 'reading'})()
